231 :         setErrorManager(
232 :             new LoggerErrorManager(createMessageFormatter(), logger));
233 :       } else {
234 :         PrintStreamErrorManager printer =
235 :             new PrintStreamErrorManager(createMessageFormatter(), outStream);
236 :         printer.setSummaryDetailLevel(options.summaryDetailLevel);
237 :         setErrorManager(printer);
238 :       }
239 :     }
240 : 
241 :     // Initialize the warnings guard.
242 :     List<WarningsGuard> guards = Lists.newArrayList();
243 :     guards.add(
244 :         new SuppressDocWarningsGuard(
245 :             getDiagnosticGroups().getRegisteredGroups()));
246 :     WarningsGuard warningsGuard = options.getWarningsGuard();
247 :     if (warningsGuard != null) {
248 :       guards.add(options.getWarningsGuard());
249 :     }
250 : 
251 :     // All passes must run the variable check. This synthesizes
252 :     // variables later so that the compiler doesn't crash. It also
253 :     // checks the externs file for validity. If you don't want to warn
254 :     // about missing variable declarations, we shut that specific
255 :     // error off.
256 :     if (!options.checkSymbols &&
257 :         (warningsGuard == null || !warningsGuard.disables(
258 :             DiagnosticGroups.CHECK_VARIABLES))) {
259 :       guards.add(new DiagnosticGroupWarningsGuard(
260 :           DiagnosticGroups.CHECK_VARIABLES, CheckLevel.OFF));
261 :     }
262 :     this.warningsGuard = new ComposeWarningsGuard(guards);
