"365 :   private void checkFirstModule(List<JSModule> modules) {
366 :     if (modules.isEmpty()) {
367 :       report(JSError.make(EMPTY_MODULE_LIST_ERROR));
368 :     } else if (modules.get(0).getInputs().isEmpty() && modules.size() > 1) {
369 :       // The root module may only be empty if there is exactly 1 module.
370 :       report(JSError.make(EMPTY_ROOT_MODULE_ERROR,
371 :           modules.get(0).getName()));
372 :     }
